import {createLocalAudioLibrary} from './local-audio-library.js';
const $=s=>document.querySelector(s),assert=(v,m)=>{if(!v)throw Error(m);};
const sha=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');
$('#run').onclick=async()=>{
  $('#run').disabled=true;const name='openplay-storage-review-'+crypto.randomUUID(),checks=[],stores=[],report={startedAt:new Date().toISOString(),name,checks,scope:'Actual browser IndexedDB transactions, structured Blob/File storage, close/reopen and integrity reads on owned synthetic fixtures. Quota failure uses an injected throw inside a real transaction; no real disk exhaustion. No main UI/native restart/audio/device/reference acceptance.'};
  let raw;
  const make=options=>{const store=createLocalAudioLibrary({name,...options});stores.push(store);return store;};
  const publish=()=>{$('#results').textContent=JSON.stringify(report,null,2);$('#status').textContent=`${checks.filter(x=>x.passed).length}/${checks.length} passed`;};
  const check=async(name,run)=>{try{const evidence=await run();checks.push({name,passed:true,evidence});}catch(error){checks.push({name,passed:false,error:error.message,stack:error.stack});}publish();};
  const rejects=async(p,name)=>{let caught;try{await p;}catch(error){caught=error;}assert(caught?.name===name,`Expected ${name}, received ${caught?.name||'success'}`);return caught.message;};
  const bytes=new Uint8Array([82,73,70,70,1,2,3,4,87,65,86,69]).buffer,hash=await sha(bytes),id='local-'+hash;
  const file=new File([bytes],'fixture-original.wav',{type:'audio/wav',lastModified:12345}),track={id,contentHash:hash,title:'Original title',duration:12,cues:[{position:2}],file,readFile:()=>file};
  let store=make();
  async function rawChange(stores,mode,run){return new Promise((resolve,reject)=>{const tx=raw.transaction(stores,mode);tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);run(tx);});}
  try{
    report.sourceHashes={};for(const file of ['local-audio-library.js','local-audio-library-harness.js'])report.sourceHashes[file]=await sha(await(await fetch(file)).arrayBuffer());
    await check('Commit original bytes and catalog metadata atomically',async()=>{const saved=await store.save(track,file,bytes);assert(saved.storage==='saved'&&saved.id===id,'Save did not commit');return{fileSize:saved.fileSize,id};});
    raw=await new Promise((resolve,reject)=>{const request=indexedDB.open(name,1);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});
    await check('List returns metadata without eagerly copying all audio blobs',async()=>{const list=await store.list();assert(list.length===1&&list[0].title==='Original title'&&!list[0].file&&!list[0].blob&&!list[0].readFile,'Invalid lightweight catalog');return{entries:list.length,filename:list[0].filename};});
    await check('Close/reopen reconstructs File with exact original bytes and attributes',async()=>{store.close();store=make();const restored=await store.file(id);assert(restored.name===file.name&&restored.lastModified===file.lastModified&&restored.type===file.type,'File attributes changed');assert(await sha(await restored.arrayBuffer())===hash,'Restored bytes changed');return{sha256:hash,bytes:restored.size};});
    await check('Duplicate content updates one stable entry instead of adding a second',async()=>{await store.save({...track,title:'Updated title'},new File([bytes],'renamed.wav',{type:file.type,lastModified:99}),bytes);const list=await store.list();assert(list.length===1&&list[0].filename==='renamed.wav'&&list[0].title==='Updated title','Duplicate identity lost');return{entries:list.length};});
    await check('False content identity is rejected before either object store changes',async()=>{await rejects(store.save({...track,contentHash:'0'.repeat(64)},file,bytes),'DataError');assert((await store.list())[0].title==='Updated title','Rejected metadata changed catalog');});
    await check('Uncloneable metadata aborts the real transaction without replacing original audio',async()=>{await rejects(store.save({...track,bad:()=>{}},file,bytes),'DataCloneError');assert((await store.list())[0].title==='Updated title','Aborted catalog replaced old value');assert(await sha(await(await store.file(id)).arrayBuffer())===hash,'Aborted save damaged audio');});
    await check('Injected quota error after catalog request rolls back real transaction',async()=>{
      const factory={open(...args){const request=indexedDB.open(...args);return new Proxy(request,{get(target,key){if(key==='result')return new Proxy(target.result,{get(database,field){if(field==='transaction')return(...args)=>{const tx=database.transaction(...args),objectStore=tx.objectStore.bind(tx);tx.objectStore=storeName=>{const object=objectStore(storeName);if(storeName==='media'&&args[1]==='readwrite')object.put=()=>{throw new DOMException('Injected quota failure','QuotaExceededError');};return object;};return tx;};const value=Reflect.get(database,field,database);return typeof value==='function'?value.bind(database):value;},set(database,field,value){return Reflect.set(database,field,value,database);}});const value=Reflect.get(target,key,target);return typeof value==='function'?value.bind(target):value;},set(target,key,value){return Reflect.set(target,key,value,target);}});}};
      const quota=make({factory});await rejects(quota.save({...track,title:'Must roll back'},file,bytes),'QuotaExceededError');assert((await store.list())[0].title==='Updated title','Catalog committed despite media failure');assert(await sha(await(await store.file(id)).arrayBuffer())===hash,'Prior audio lost after quota failure');quota.close();return{failure:'injected',transaction:'real browser IndexedDB'};
    });
    await check('Corrupted stored bytes fail their hash instead of silently decoding wrong media',async()=>{await rawChange(['media'],'readwrite',tx=>tx.objectStore('media').put({id,blob:new Blob(['different'])}));return{error:await rejects(store.file(id),'DataError')};});
    await check('Missing media record is explicit while catalog identity remains recoverable',async()=>{await rawChange(['media'],'readwrite',tx=>tx.objectStore('media').delete(id));await rejects(store.file(id),'NotFoundError');assert((await store.list())[0].id===id,'Recovery metadata lost');});
    await check('Reimport repairs missing audio under the same stable content identity',async()=>{await store.save(track,file,bytes);assert(await sha(await(await store.file(id)).arrayBuffer())===hash,'Repair failed');assert((await store.list()).length===1,'Repair duplicated row');});
    await check('Concurrent distinct imports commit two catalog/media pairs',async()=>{const second=new Uint8Array([9,8,7,6]).buffer,h=await sha(second),other={id:'local-'+h,contentHash:h,title:'Second',duration:1};await Promise.all([store.save(track,file,bytes),store.save(other,new File([second],'second.wav'),second)]);assert((await store.list()).length===2,'Concurrent entries missing');assert(await sha(await(await store.file(other.id)).arrayBuffer())===h,'Second bytes wrong');});
    await check('Close while hashing prevents a late save and refuses subsequent operations',async()=>{const closing=make(),pending=closing.save(track,file,bytes);closing.close();await rejects(pending,'InvalidStateError');await rejects(closing.list(),'InvalidStateError');assert((await store.list()).length===2,'Closed owner changed catalog');});
    await check('Unavailable storage rejects explicitly rather than claiming a saved file',async()=>{const absent=make({factory:null});await rejects(absent.list(),'NotSupportedError');await rejects(absent.save(track,file,bytes),'NotSupportedError');absent.close();});
  }catch(error){report.fatalError={message:error.message,stack:error.stack};}
  finally{
    for(const store of stores)store.close();raw?.close();
    try{await new Promise((resolve,reject)=>{const request=indexedDB.deleteDatabase(name);request.onsuccess=resolve;request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('Owned test database cleanup blocked'));});report.ownedTestDatabaseRemoved=true;}catch(error){report.cleanupError=error.message;}
    report.passed=checks.filter(x=>x.passed).length;report.failed=checks.length-report.passed;report.completed=checks.length===13&&!report.failed&&!report.fatalError&&!report.cleanupError;publish();const link=$('#download');link.href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));link.download='local-audio-library-browser-results.json';link.hidden=false;$('#run').disabled=false;
  }
};
